UPDATE pcd_user_quota_table
SET quota_used_capacity = quota_used_capacity + #{size},
    quota_version = quota_version + 1
WHERE quota_user_id = #{user_id, typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND quota_used_capacity + #{size} <= quota_total_capacity
  AND quota_version = #{version}

UPDATE pcd_user_quota_table
SET quota_used_capacity = quota_used_capacity - #{size},
    quota_version = quota_version + 1
WHERE quota_user_id = #{user_id, typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND quota_used_capacity >= #{size}
  AND quota_version = #{version}

UPDATE pcd_user_quota_table
SET quota_used_capacity = quota_used_capacity - #{size},
    quota_file_count = quota_file_count - 1,
    quota_version = quota_version + 1
WHERE quota_user_id = #{user_id, typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND quota_used_capacity >= #{size}
  AND quota_file_count >= 1
  AND quota_version = #{version}

UPDATE pcd_user_quota_table
SET quota_released_capacity = quota_released_capacity + #{size},
    quota_version = quota_version + 1
WHERE quota_user_id = #{user_id, typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND quota_total_capacity - (quota_used_capacity + quota_released_capacity) >= #{size}
  AND quota_version = #{version}

UPDATE pcd_user_quota_table
SET quota_released_capacity = quota_released_capacity - #{size},
    quota_used_capacity = quota_used_capacity + #{size},
    quota_file_count = quota_file_count + 1,
    quota_version = quota_version + 1
WHERE quota_user_id = #{user_id, typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND quota_released_capacity >= #{size}
  AND quota_version = #{version}

UPDATE pcd_user_quota_table
SET quota_released_capacity = quota_released_capacity - #{size},
    quota_version = quota_version + 1
WHERE quota_user_id = #{user_id, typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND quota_released_capacity >= #{size}
  AND quota_version = #{version}
